from __future__ import annotations
from typing import List, Sequence
Complex = complex

def conj_vec(x: Sequence[Complex]) -> List[Complex]:
    return [v.conjugate() for v in x]

def dot(v: Sequence[Complex], w: Sequence[Complex]) -> Complex:
    return sum((a * b for a, b in zip(v, w)), 0j)

def mat_vec(h: List[List[Complex]], x: Sequence[Complex]) -> List[Complex]:
    return [sum((h[i][j] * x[j] for j in range(len(x))), 0j) for i in range(len(h))]

def qform(h: List[List[Complex]], x: Sequence[Complex]) -> Complex:
    return dot(conj_vec(x), mat_vec(h, x))

def mat_add(a, b):
    return [[a[i][j] + b[i][j] for j in range(len(a[i]))] for i in range(len(a))]

H_Z = [[0j, 0j], [0j, 1+0j]]
H_X = [[0.5+0j, -0.5+0j], [-0.5+0j, 0.5+0j]]
x = [0.6+0.2j, -0.3+0.5j]
print("additive:", abs(qform(mat_add(H_Z, H_X), x) - (qform(H_Z, x) + qform(H_X, x))) < 1e-12)
print("Hermitian H_Z energy imag:", qform(H_Z, x).imag)
non_herm = [[0j, 1j], [0j, 0j]]
print("non-Hermitian energy:", qform(non_herm, [1+0j, 1+0j]))

from __future__ import annotations
import math, random
from typing import List, Sequence, Tuple
Complex = complex

def dot(v, w):
    return sum((a * b for a, b in zip(v, w)), 0j)

def norm_sq(x):
    return dot([c.conjugate() for c in x], x).real

def qform(h, x):
    hx = [sum((h[i][j] * x[j] for j in range(len(x))), 0j) for i in range(len(h))]
    return dot([c.conjugate() for c in x], hx)

def energy_lb(h, lam, samples=4000) -> bool:
    rng = random.Random(7)
    for _ in range(samples):
        x = [complex(rng.gauss(0,1), rng.gauss(0,1)) for _ in range(len(h))]
        if lam * norm_sq(x) > qform(h, x).real + 1e-9:
            return False
    return True

def eig_min(a) -> float:
    a00, a11 = a[0][0].real, a[1][1].real
    off = a[0][1]
    tr = a00 + a11
    det = a00 * a11 - (off * off.conjugate()).real
    return tr/2 - math.sqrt(max(tr*tr/4 - det, 0.0))

H = [[0.5+0j, -0.5+0j], [-0.5+0j, 1.5+0j]]   # = H_Z + H_X
a, b = 0.10, 0.40
yes = eig_min(H) <= a
no = energy_lb(H, b)
print("YES:", yes, " NO:", no, " both:", yes and no)

