function AdditiveCertificate(terms H_1..H_m):
    total <- 0
    for i in 1..m:
        lambda_i <- smallest_eigenvalue(H_i)   # Hermitian eigensolve, O(d_i^3)
        assert EnergyLB(H_i, lambda_i)          # certificate for term i
        total <- total + lambda_i               # additive composition
    return total   # certified: EnergyLB(sum_i H_i, total)
